/* ===================== 渲染展示架 ===================== */
function renderShelf() {
  const boards = $('shelf-boards');
  boards.innerHTML = '';
  // 每行 3 个胶片，共 9 个 → 3 行
  const perRow = 3;
  const rows = Math.ceil(data.films.length / perRow);
  for (let r = 0; r < rows; r++) {
    const row = document.createElement('div');
    row.className = 'shelf-row';
    for (let i = r * perRow; i < Math.min((r + 1) * perRow, data.films.length); i++) {
      const film = data.films[i];
      const cover = getFilmCover(film);
      const el = document.createElement('div');
      el.className = 'film' + (cover ? ' has-cover' : '');
      el.dataset.idx = i;
      el.innerHTML = `
        <div class="film-cover">
          <div class="film-red-circle">
            <span class="film-plus">+</span>
            ${cover ? `<img src="${cover}" alt="${film.name}" onerror="this.style.display='none';this.closest('.film').classList.remove('has-cover');">` : ''}
          </div>
        </div>
        <div class="film-label" title="点击编辑名称">${film.name}</div>
      `;
      el.addEventListener('click', () => onFilmClick(i));
      // 胶片名称：点击即可编辑，回车确认
      const label = el.querySelector('.film-label');
      label.addEventListener('click', (e) => {
        e.stopPropagation();
        if (label.isContentEditable) return;
        label.contentEditable = 'true';
        label.focus();
        const range = document.createRange();
        range.selectNodeContents(label);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      });
      label.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); label.blur(); }
        if (e.key === 'Escape') { e.preventDefault(); label.textContent = film.name; label.blur(); }
      });
      label.addEventListener('blur', () => {
        label.contentEditable = 'false';
        const newName = label.textContent.trim() || (i === 0 ? '作者精选' : '待命名胶片');
        if (newName !== film.name) {
          data.films[i].name = newName;
          saveToStorage();
          toast('胶片名称已更新');
        }
        label.textContent = newName;
      });
      row.appendChild(el);
    }
    boards.appendChild(row);
  }
}

/* ===================== 场景切换 ===================== */
function showScene(id) {
  document.querySelectorAll('.scene').forEach(s => s.classList.remove('active'));
  $(id).classList.add('active');
}

/* ===================== 相机移动 ===================== */
function setCamera(view) {
  const w = $('stage-world');
  // view: 'overview' / 'shelf' / 'player' / 'center'
  if (view === 'overview' || view === 'shelf') {
    // 默认视角：从小猫身后看展示架
    w.style.transform = 'scale(1)';
  } else if (view === 'center') {
    // 过渡：轻微缩小
    w.style.transform = 'scale(0.96)';
  } else if (view === 'player') {
    // 放大并移到右下角唱片机
    w.style.transform = 'scale(1.5) translate(-28%, -22%)';
  }
}

/* ===================== 人物移动 ===================== */
function moveCharacterTo(xPercent) {
  const c = $('character');
  c.style.left = xPercent + '%';
  c.classList.add('walking');
  return wait(1600).then(() => c.classList.remove('walking'));
}

/* ===================== 形象选择 ===================== */
function initSelectScene() {
  const cards = document.querySelectorAll('.char-card');
  cards.forEach(card => {
    card.addEventListener('click', () => {
      cards.forEach(c => c.classList.remove('selected'));
      card.classList.add('selected');
      data.gender = card.dataset.gender;
      $('confirm-char').disabled = false;
    });
  });
  $('char-name-input').addEventListener('input', e => {
    data.name = e.target.value;
  });
  $('confirm-char').addEventListener('click', () => {
    if (!data.gender) { toast('请先选择形象'); return; }
    saveToStorage();
    enterStage();
  });
}

/* ===================== 进入主舞台 ===================== */
function enterStage() {
  showScene('scene-stage');
  // 渲染人物
  $('char-svg').outerHTML = renderCharSVG(data.gender).replace('<svg viewBox="0 0 130 220">', '<svg id="char-svg" viewBox="0 0 130 220">');
  $('character').style.display = 'block';
  // 设置手臂颜色和位置（基于角色实际像素尺寸）
  const charEl = $('character');
  const armColor = data.gender === 'for_love' ? '#2a4a8a' : '#7ac4a8';
  const handColor = data.gender === 'for_love' ? '#fafafa' : '#f5e6d0';
  charEl.style.setProperty('--arm-color', armColor);
  charEl.style.setProperty('--hand-color', handColor);
  // 角色尺寸确定后计算肩膀像素位置
  requestAnimationFrame(() => {
    const rect = charEl.getBoundingClientRect();
    const sx = 92 * rect.width / 130;  // 肩膀中心 X（SVG 92）
    const sy = 92 * rect.height / 220; // 肩膀顶部 Y（SVG 92）
    charEl.style.setProperty('--shoulder-x', (sx - 6) + 'px'); // 减去半臂宽
    charEl.style.setProperty('--shoulder-y', sy + 'px');
    charEl.style.setProperty('--arm-length', '48px');
    charEl.style.setProperty('--arm-angle', '0deg');
  });
  // 渲染展示架
  renderShelf();
  // 渲染对话
  $('custom-text').textContent = data.customText || '记忆小屋';
  // 初始位置和视角
  $('character').style.left = '50%';
  setCamera('overview');
  // 隐藏气泡与提示
  $('speech-bubble').classList.remove('show');
  $('prompt').classList.remove('show');
  state = 'STAGE_INTRO';
  toast('点击人物开始');
}

/* ===================== 点击人物 ===================== */
function onCharacterClick() {
  if (state === 'STAGE_INTRO') {
    speak();
  }
}

/* ===================== 说话 ===================== */
function speak() {
  state = 'SPEAKING';
  const bubble = $('speech-bubble');
  const customText = $('custom-text');
  customText.contentEditable = 'true';
  bubble.classList.add('show');
  toast('可点击蓝色文字自定义，再次点击人物继续');

  // 等待用户点击"继续"
  // 这里简化为：用户编辑完文字后，点击空白处或人物继续
  const continueHandler = (e) => {
    // 点击人物或气泡以外的地方继续
    if (e.target.closest('#character') || e.target.closest('#speech-bubble')) {
      if (e.target.id === 'custom-text') return; // 编辑中
      if (e.target.closest('#character')) {
        // 第二次点击人物 = 继续
        document.removeEventListener('click', continueHandler, true);
        finishSpeak();
      }
      return;
    }
    document.removeEventListener('click', continueHandler, true);
    finishSpeak();
  };
  // 监听一次气泡外点击
  setTimeout(() => {
    document.addEventListener('click', continueHandler, true);
  }, 100);

  // 2.5秒后不再重复提示
  // setTimeout removed - merged into toast above
}

function finishSpeak() {
  if (state !== 'SPEAKING') return;
  // 保存自定义文本
  data.customText = $('custom-text').textContent.trim() || '记忆小屋';
  $('custom-text').contentEditable = 'false';
  saveToStorage();
  $('speech-bubble').classList.remove('show');
  // 走到展示架
  walkToShelf();
}

async function walkToShelf() {
  state = 'WALKING';
  await wait(400);
  state = 'SHELF';
  $('prompt').textContent = '请点击任意记忆胶片'; $('prompt').style.top = ''; $('prompt').style.bottom = '';
  $('prompt').classList.add('show');
}

/* ===================== 点击胶片 ===================== */
async function onFilmClick(idx) {
  if (state !== 'SHELF') return;
  const film = data.films[idx];
  // "作者精选"胶片已固定，直接进入图集
  if (film.fixed) {
    currentFilmIndex = idx;
    // 直接走取胶片→唱片机流程
  } else if (!film.images || film.images.length === 0) {
    // 没有图片 → 直接调起相册选择
    currentFilmIndex = idx;
    const filmObj = film;
    const applyImages = (imgs) => {
      if (!imgs || imgs.length === 0) return;
      if (!filmObj.cover && filmObj.images.length === 0) {
        filmObj.cover = imgs[0];
      }
      filmObj.images = filmObj.images.concat(imgs).slice(0, MAX_IMAGES);
      saveToStorage();
      renderShelf();
      toast(`已添加 ${imgs.length} 张照片`);
      currentFilmIndex = -1;
    };
    if (window.__SUPPORT && window.__SUPPORT.fileInput) {
      const picker = $('file-picker');
      picker.value = '';
      picker.onchange = async (e) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;
        const newImgs = await processFiles(files, MAX_IMAGES);
        applyImages(newImgs);
      };
      picker.click();
    } else {
      fallbackImageInput((dataUrl) => applyImages([dataUrl]));
    }
    return;
  }
  currentFilmIndex = idx;
  try { prepareMusic(); } catch(e) { console.error('prepareMusic err:', e); }
  state = 'TAKING';
  $('prompt').classList.remove('show');

  const filmEl = document.querySelector(`.film[data-idx="${idx}"]`);
  const charEl = $('character');
  const handFilm = $('film-in-hand');
  const filmRect = filmEl.getBoundingClientRect();
  const charRect = charEl.getBoundingClientRect();
  const playerRect = $('record-player').getBoundingClientRect();

  // 肩膀在角色内的像素坐标（SVG 原点 (0,0) 对应角色左上角）
  const SHOULDER_SVG_X = 92, SHOULDER_SVG_Y = 92;
  const shoulderPx = {
    x: SHOULDER_SVG_X * charRect.width / 130,
    y: SHOULDER_SVG_Y * charRect.height / 220
  };

  // 1. 计算目标手位置（胶片中心相对于角色左上角的像素坐标）
  const targetFilm = {
    x: filmRect.left + filmRect.width / 2 - charRect.left,
    y: filmRect.top + filmRect.height / 2 - charRect.top
  };

  // 计算手臂参数
  const deltaX = targetFilm.x - shoulderPx.x;
  const deltaY = targetFilm.y - shoulderPx.y;
  const armLength = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
  const armAngle = Math.atan2(deltaX, deltaY) * 180 / Math.PI;

  // 设置手臂位置
  charEl.style.setProperty('--shoulder-x', (shoulderPx.x - 6) + 'px');
  charEl.style.setProperty('--shoulder-y', shoulderPx.y + 'px');
  charEl.style.setProperty('--arm-length', armLength + 'px');
  charEl.style.setProperty('--arm-angle', armAngle + 'deg');

  // 手中胶片定位到胶片位置（使用固定像素大小，与展示架胶片完全一致）
  handFilm.style.width = filmRect.width + 'px';
  handFilm.style.height = filmRect.height + 'px';
  handFilm.style.top = (targetFilm.y - filmRect.height / 2) + 'px';
  handFilm.style.left = (targetFilm.x - filmRect.width / 2) + 'px';
  handFilm.style.opacity = '';
  $('film-in-hand-img').src = getFilmCover(film);

  charEl.classList.add('reaching');
  charEl.classList.add('holding');
  filmEl.classList.add('taken');
  await wait(700);

  // 2. 手中胶片移动到唱片机（大小不变）
  const targetPlayer = {
    x: playerRect.left + playerRect.width / 2 - charRect.left,
    y: playerRect.top + playerRect.height / 2 - charRect.top
  };

  // 手臂跟随胶片到唱片机
  const deltaX2 = targetPlayer.x - shoulderPx.x;
  const deltaY2 = targetPlayer.y - shoulderPx.y;
  const armLength2 = Math.sqrt(deltaX2 * deltaX2 + deltaY2 * deltaY2);
  const armAngle2 = Math.atan2(deltaX2, deltaY2) * 180 / Math.PI;

  charEl.style.setProperty('--arm-length', armLength2 + 'px');
  charEl.style.setProperty('--arm-angle', armAngle2 + 'deg');

  handFilm.style.transition = 'top 0.6s ease-in-out, left 0.6s ease-in-out';
  handFilm.style.top = (targetPlayer.y - filmRect.height / 2) + 'px';
  handFilm.style.left = (targetPlayer.x - filmRect.width / 2) + 'px';
  await wait(600);

  // 3. 唱片机显示胶片
  $('player-film').style.display = 'block';
  $('turntable-disc').classList.add('spinning');
  spawnNotes();

  // 4. 手收回（手臂恢复自然下垂）
  handFilm.style.opacity = '0';
  charEl.classList.remove('reaching');
  charEl.classList.remove('holding');
  charEl.style.setProperty('--arm-length', '48px');
  charEl.style.setProperty('--arm-angle', '0deg');
  handFilm.style.transition = '';
  handFilm.style.top = '';
  handFilm.style.right = '';
  handFilm.style.opacity = '';
  await wait(700);

  state = 'PLAYER';
  startMusic(); // 胶片放上唱片机开始播放音乐
  $('prompt').textContent = '点击唱片机进入'; $('prompt').style.top = '2%'; $('prompt').style.bottom = 'auto';
  $('prompt').classList.add('show');
}

/* ===================== 音符 ===================== */
function spawnNotes() {
  const container = $('notes-container');
  container.innerHTML = '';
  const notes = ['♪', '♫', '♩', '♬', '♭', '♮'];
  const total = 14;
  let i = 0;
  const interval = setInterval(() => {
    if (i >= total) { clearInterval(interval); return; }
    const n = document.createElement('div');
    n.className = 'music-note';
    n.textContent = notes[Math.floor(Math.random() * notes.length)];
    // 在右下角唱片机附近（70-92% 左右，5-30% 底部）
    n.style.left = (70 + Math.random() * 22) + '%';
    n.style.bottom = (8 + Math.random() * 22) + '%';
    n.style.fontSize = (16 + Math.random() * 14) + 'px';
    container.appendChild(n);
    setTimeout(() => n.remove(), 2500);
    i++;
  }, 350);
}

/* ===================== 进入图集 ===================== */
function enterGallery() {
  if (state !== 'PLAYER') return;
  const film = data.films[currentFilmIndex];
  if (!film.images || film.images.length === 0) {
    toast('该胶片没有图集');
    return;
  }
  state = 'GALLERY';
  galleryIndex = 0;
  $('gallery-name').textContent = film.name;
  showScene('scene-gallery');
  // 显示添加照片按钮
  $('gallery-add-btn').classList.add('show');
  renderGalleryImage();
}

function renderGalleryImage() {
  const film = data.films[currentFilmIndex];
  const img = $('gallery-image');
  img.style.opacity = '0';
  setTimeout(() => {
    img.src = film.images[galleryIndex];
    img.onload = () => { img.style.opacity = '1'; };
    img.style.transition = 'opacity 0.4s';
  }, 200);
  $('gallery-counter').textContent = `${galleryIndex + 1} / ${film.images.length}`;
  $('nav-prev').disabled = galleryIndex === 0;
  $('nav-next').disabled = galleryIndex === film.images.length - 1;
  // 更新添加按钮可见性（固定胶片不显示添加按钮）
  const addBtn = $('gallery-add-btn');
  if (!film.fixed && film.images.length < MAX_IMAGES) {
    addBtn.classList.add('show');
    addBtn.textContent = `+ 添加照片 (${MAX_IMAGES - film.images.length})`;
  } else {
    addBtn.classList.remove('show');
  }
}

/* ===== EMBEDDED MUSIC (Base64, 13 songs x 60s) ===== */
// Embedded music (Base64, 60s clip, 11025Hz mono 24kbps, 13 songs)
const MUSIC_B64 = {
  'curated.mp3': './audios/curated.mp3',
  'lovelife1.mp3': './audios/lovelife1.mp3',
  'lovelife2.mp3': './audios/lovelife2.mp3',
  'lovelife3.mp3': './audios/lovelife3.mp3',
  'lovelife4.mp3': './audios/lovelife4.mp3',
  'lovelife5.mp3': './audios/lovelife5.mp3',
  'lovelife6.mp3': './audios/lovelife6.mp3',
  'forlove1.mp3': './audios/forlove1.mp3',
  'forlove2.mp3': './audios/forlove2.mp3',
  'forlove3.mp3': './audios/forlove3.mp3',
  'forlove4.mp3': './audios/forlove4.mp3',
  'forlove5.mp3': './audios/forlove5.mp3',
  'forlove6.mp3': './audios/forlove6.mp3'
};

const BGM_GROUPS = {
  love_life: Array.from({length: 6}, (_, i) => MUSIC_B64['lovelife' + (i+1) + '.mp3']),
  for_love:  Array.from({length: 6}, (_, i) => MUSIC_B64['forlove' + (i+1) + '.mp3']),
};
const BGM_CURATED = MUSIC_B64['curated.mp3'];


let audioUnlocked = false;
let bgmAudio = null;
function initAudio() {
  if (!bgmAudio) {
    bgmAudio = new Audio();
    bgmAudio.loop = true;
    bgmAudio.volume = 0.6;
    bgmAudio.src = BGM_CURATED;
  }
}
function unlockAudio() {
  if (audioUnlocked) return;
  initAudio();
  bgmAudio.volume = 0;
  bgmAudio.play().then(function() {
    bgmAudio.pause();
    bgmAudio.volume = 0.6;
    bgmAudio.currentTime = 0;
    audioUnlocked = true;
  }).catch(function() {
    bgmAudio.volume = 0.6;
    audioUnlocked = true;
  });
}
document.addEventListener('click', unlockAudio, { once: true });
function prepareMusic() {
  initAudio();
  const film = data.films[currentFilmIndex];
  let src;
  if (film && film.fixed) {
    src = BGM_CURATED;
  } else {
    const list = BGM_GROUPS[data.gender] || BGM_GROUPS.love_life;
    let idx;
    if (list.length > 1) {
      do { idx = Math.floor(Math.random() * list.length); } while (idx === currentBgmIdx);
    } else {
      idx = 0;
    }
    currentBgmIdx = idx;
    src = list[idx];
  }
  bgmAudio.volume = 0;
  try { bgmAudio.src = src; bgmAudio.play().catch(() => {}); } catch(e) { console.error('play err:', e); }
}

function startMusic() {
  if (!bgmAudio) { prepareMusic(); }
  bgmAudio.volume = 0.6;
}

function stopMusic() {
  if (!bgmAudio) return;
  bgmAudio.pause();
  bgmAudio.currentTime = 0;
  currentBgmIdx = -1;
}

/* ===================== 返回唱片机界面 ===================== */
async function backFromGallery() {
  $('gallery-add-btn').classList.remove('show');
  showScene('scene-stage');
  state = 'RETURNING';
  await wait(300);
  // 手臂伸长取回胶片（从唱片机位置）
  const charEl = $('character');
  const handFilm = $('film-in-hand');
  $('player-film').style.display = 'none';
  $('turntable-disc').classList.remove('spinning');
  $('notes-container').innerHTML = '';
  await wait(300);

  // 计算角色和胶片位置
  const filmEl = document.querySelector(`.film[data-idx="${currentFilmIndex}"]`);
  const charRect = charEl.getBoundingClientRect();
  const filmRect = filmEl.getBoundingClientRect();

  const SHOULDER_SVG_X = 92, SHOULDER_SVG_Y = 92;
  const shoulderPx = {
    x: SHOULDER_SVG_X * charRect.width / 130,
    y: SHOULDER_SVG_Y * charRect.height / 220
  };

  // 手臂先伸到胶片位置
  const targetFilm = {
    x: filmRect.left + filmRect.width / 2 - charRect.left,
    y: filmRect.top + filmRect.height / 2 - charRect.top
  };

  const deltaX = targetFilm.x - shoulderPx.x;
  const deltaY = targetFilm.y - shoulderPx.y;
  const armLength = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
  const armAngle = Math.atan2(deltaX, deltaY) * 180 / Math.PI;

  charEl.style.setProperty('--shoulder-x', (shoulderPx.x - 6) + 'px');
  charEl.style.setProperty('--shoulder-y', shoulderPx.y + 'px');
  charEl.style.setProperty('--arm-length', armLength + 'px');
  charEl.style.setProperty('--arm-angle', armAngle + 'deg');

  // 手中胶片定位到胶片位置（固定像素大小，与展示架一致）
  handFilm.style.width = filmRect.width + 'px';
  handFilm.style.height = filmRect.height + 'px';
  handFilm.style.top = (targetFilm.y - filmRect.height / 2) + 'px';
  handFilm.style.left = (targetFilm.x - filmRect.width / 2) + 'px';
  handFilm.style.opacity = '';
  $('film-in-hand-img').src = getFilmCover(data.films[currentFilmIndex]);

  charEl.classList.add('reaching');
  charEl.classList.add('holding');
  await wait(700);

  // 胶片放回展示架
  if (filmEl) filmEl.classList.remove('taken');

  // 手臂收回（恢复自然下垂）
  charEl.classList.remove('reaching');
  charEl.classList.remove('holding');
  charEl.style.setProperty('--arm-length', '48px');
  charEl.style.setProperty('--arm-angle', '0deg');
  handFilm.style.transition = '';
  handFilm.style.top = '';
  handFilm.style.right = '';
  handFilm.style.opacity = '';
  currentFilmIndex = -1;
  state = 'SHELF';
  stopMusic(); // 胶片放回展示架停止音乐
  $('prompt').textContent = '请点击任意记忆胶片'; $('prompt').style.top = ''; $('prompt').style.bottom = '';
  $('prompt').classList.add('show');
}

/* ===================== 回到初始界面 ===================== */
function returnToSelect() {
  // 重置舞台状态
  const charEl = $('character');
  charEl.classList.remove('holding', 'reaching', 'walking');
  charEl.style.setProperty('--arm-length', '48px');
  charEl.style.setProperty('--arm-angle', '0deg');
  $('film-in-hand').style.opacity = '';
  $('film-in-hand').style.top = '';
  $('film-in-hand').style.left = '';
  $('film-in-hand').style.width = '';
  $('film-in-hand').style.height = '';
  $('film-in-hand').style.transition = '';
  $('player-film').style.display = 'none';
  $('turntable-disc').classList.remove('spinning');
  $('notes-container').innerHTML = '';
  stopMusic(); // 返回初始界面停止音乐
  $('speech-bubble').classList.remove('show');
  $('prompt').classList.remove('show');
  document.querySelectorAll('.film.taken').forEach(f => f.classList.remove('taken'));
  currentFilmIndex = -1;
  state = 'SELECT';
  showScene('scene-select');
}

/* ===================== 编辑弹窗 ===================== */
function openEditModal() {
  $('edit-name').value = data.name || '';
  $('edit-custom-text').value = data.customText || '记忆小屋';
  renderFilmsEditList();
  $('edit-modal').classList.add('show');
}
function renderFilmsEditList() {
  const list = $('films-edit-list');
  list.innerHTML = '';
  data.films.forEach((film, idx) => {
    const row = document.createElement('div');
    row.className = 'film-edit-row';
    row.innerHTML = `
      <div class="row-head">
        <span class="row-title">胶片 ${idx + 1} · ${film.name}</span>
        <button class="remove-btn" data-idx="${idx}">删除</button>
      </div>
      <div class="field"><label>名称</label><input type="text" data-field="name" value="${film.name}" placeholder="${idx === 0 ? '作者精选' : '待命名胶片'}"></div>
      <div class="field">
        <label>封面图片（可选，留空则使用第一张图集图片）</label>
        <div class="cover-pick-area" data-idx="${idx}">
          ${film.cover ? `<div class="current-cover"><img src="${film.cover}" alt="封面"><button class="remove-cover" data-idx="${idx}">×</button></div>` : '<span style="color:#9d92c0;font-size:12px;">未设置（将自动使用第一张图集）</span>'}
          <button class="btn-pick cover-pick-btn" data-idx="${idx}">📷 选择封面</button>
        </div>
      </div>
      <div class="field">
        <label>图集图片（最多 ${MAX_IMAGES} 张，支持多选）</label>
        <div class="thumb-grid" data-idx="${idx}"></div>
        <button class="btn-pick gallery-pick-btn" data-idx="${idx}">📷 添加照片</button>
        <span class="img-count" data-idx="${idx}">${(film.images || []).length} / ${MAX_IMAGES}</span>
      </div>
    `;
    list.appendChild(row);
  });
  // 渲染每个胶片的缩略图
  list.querySelectorAll('.film-edit-row').forEach(row => {
    const idx = parseInt(row.querySelector('.gallery-pick-btn').dataset.idx);
    const film = data.films[idx];
    const grid = row.querySelector('.thumb-grid');
    (film.images || []).forEach((src, i) => {
      const div = document.createElement('div');
      div.className = 'thumb';
      div.innerHTML = `<img src="${src}" alt=""><button class="del" data-imgidx="${i}" data-filmidx="${idx}">×</button>`;
      grid.appendChild(div);
    });
  });
  // 绑定删除胶片
  list.querySelectorAll('.remove-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.idx);
      data.films.splice(idx, 1);
      renderFilmsEditList();
    });
  });
  // 绑定删除单张图片
  list.querySelectorAll('.thumb-grid').forEach(grid => {
    grid.addEventListener('click', (e) => {
      if (e.target.classList.contains('del')) {
        const imgIdx = parseInt(e.target.dataset.imgidx);
        const filmIdx = parseInt(e.target.dataset.filmidx);
        data.films[filmIdx].images.splice(imgIdx, 1);
        // 如果封面就是被删的图片，清空 cover
        if (data.films[filmIdx].cover === (film_getDeletedCover(filmIdx, imgIdx))) {
          data.films[filmIdx].cover = '';
        }
        saveToStorage();
        renderFilmsEditList();
      }
    });
  });
  // 绑定选择封面
  list.querySelectorAll('.cover-pick-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.idx);
      openInlinePicker(idx, 'cover');
    });
  });
  // 绑定选择图集
  list.querySelectorAll('.gallery-pick-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.idx);
      const remaining = MAX_IMAGES - (data.films[idx].images || []).length;
      if (remaining <= 0) { toast(`已达到上限 ${MAX_IMAGES} 张`); return; }
      openInlinePicker(idx, 'gallery');
    });
  });
  // 绑定删除封面
  list.querySelectorAll('.remove-cover').forEach(btn => {
    btn.addEventListener('click', () => {
      const idx = parseInt(btn.dataset.idx);
      data.films[idx].cover = '';
      saveToStorage();
      renderFilmsEditList();
    });
  });
}

/* 辅助：获取某胶片被删的封面值 */
function film_getDeletedCover(filmIdx, imgIdx) {
  // 返回被删除的图片 dataURL，用于判断是否等于 cover
  return data.films[filmIdx] && data.films[filmIdx].images ? data.films[filmIdx].images[imgIdx] : '';
}

/* 内联文件选择（用于编辑弹窗中选择封面/图集） */
function openInlinePicker(filmIdx, mode) {
  const film = data.films[filmIdx];
  if (window.__SUPPORT && window.__SUPPORT.fileInput) {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    if (mode === 'gallery') input.multiple = true;
    input.onchange = async (e) => {
      const files = e.target.files;
      if (!files || files.length === 0) return;
      if (mode === 'cover') {
        const data = await compressImage(files[0]);
        if (data) {
          film.cover = data;
          saveToStorage();
          renderFilmsEditList();
          toast('封面已更新');
        }
      } else {
        const remaining = MAX_IMAGES - (film.images || []).length;
        if (remaining <= 0) { toast(`已达到上限 ${MAX_IMAGES} 张`); return; }
        const newImgs = await processFiles(files, remaining);
        if (newImgs.length > 0) {
          film.images = film.images.concat(newImgs);
          saveToStorage();
          renderFilmsEditList();
          toast(`已添加 ${newImgs.length} 张照片`);
        }
      }
    };
    input.click();
  } else {
    // 降级：URL 输入
    fallbackImageInput((dataUrl) => {
      if (mode === 'cover') {
        film.cover = dataUrl;
        toast('封面已更新');
      } else {
        const remaining = MAX_IMAGES - (film.images || []).length;
        if (remaining <= 0) { toast(`已达到上限 ${MAX_IMAGES} 张`); return; }
        film.images = film.images.concat([dataUrl]);
        toast('已添加 1 张照片');
      }
      saveToStorage();
      renderFilmsEditList();
    });
  }
}

/* 兼容性：如果文件选择器不可用，提供降级 URL 输入 */
function fallbackImageInput(onResult) {
  const url = prompt('当前环境可能不支持相册选择。\n请粘贴图片 URL 链接：');
  if (!url) return;
  const img = new Image();
  img.crossOrigin = 'anonymous';
  img.onload = () => {
    const canvas = document.createElement('canvas');
    let { width, height } = img;
    const scale = Math.min(1, 800 / width, 800 / height);
    if (scale < 1) { width = Math.round(width * scale); height = Math.round(height * scale); }
    canvas.width = width; canvas.height = height;
    canvas.getContext('2d').drawImage(img, 0, 0, width, height);
    onResult(canvas.toDataURL('image/jpeg', 0.75));
  };
  img.onerror = () => toast('图片加载失败，请检查链接');
  img.src = url;
}
function saveEditModal() {
  data.name = $('edit-name').value.trim();
  data.customText = $('edit-custom-text').value.trim() || '记忆小屋';
  // 从行中同步名称（封面和图片已通过 openInlinePicker 实时保存）
  const rows = document.querySelectorAll('.film-edit-row');
  rows.forEach((row, idx) => {
    const nameInput = row.querySelector('[data-field="name"]');
    if (nameInput && data.films[idx]) {
      data.films[idx].name = nameInput.value.trim() || (idx === 0 ? '作者精选' : '待命名胶片');
    }
  });
  saveToStorage();
  $('edit-modal').classList.remove('show');
  // 重新渲染当前场景
  if ($('scene-stage').classList.contains('active')) {
    $('custom-text').textContent = data.customText;
    renderShelf();
  }
  toast('已保存');
}

/* ===================== 绑定事件 ===================== */
function bindEvents() {
  $('character').addEventListener('click', onCharacterClick);
  $('record-player').addEventListener('click', () => {
    if (state === 'PLAYER') enterGallery();
  });
  $('back-btn').addEventListener('click', backFromGallery);
  $('nav-prev').addEventListener('click', () => {
    if (galleryIndex > 0) { galleryIndex--; renderGalleryImage(); }
  });
  $('nav-next').addEventListener('click', () => {
    const film = data.films[currentFilmIndex];
    if (galleryIndex < film.images.length - 1) { galleryIndex++; renderGalleryImage(); }
  });
  // 键盘左右
  document.addEventListener('keydown', e => {
    if (state !== 'GALLERY') return;
    if (e.key === 'ArrowLeft') $('nav-prev').click();
    if (e.key === 'ArrowRight') $('nav-next').click();
    if (e.key === 'Escape') $('back-btn').click();
  });
  // 主舞台胶片文件选择（点击空胶片时触发）
  $('file-picker').addEventListener('change', async (e) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    if (currentFilmIndex < 0) return;
    const film = data.films[currentFilmIndex];
    const newImgs = await processFiles(files, MAX_IMAGES);
    if (newImgs.length > 0) {
      // 如果是第一次添加，第一张作为封面
      if (!film.cover && film.images.length === 0) {
        film.cover = newImgs[0];
      }
      film.images = film.images.concat(newImgs).slice(0, MAX_IMAGES);
      saveToStorage();
      renderShelf();
      toast(`已添加 ${newImgs.length} 张照片`);
    }
    currentFilmIndex = -1;
  });
  // 相册内添加更多照片
  $('gallery-add-btn').addEventListener('click', () => {
    const film = data.films[currentFilmIndex];
    if (!film || film.fixed) return;
    const remaining = MAX_IMAGES - (film.images || []).length;
    if (remaining <= 0) { toast(`已达到上限 ${MAX_IMAGES} 张`); return; }
    if (window.__SUPPORT && window.__SUPPORT.fileInput) {
      const picker = $('file-picker-gallery');
      picker.value = '';
      picker.click();
    } else {
      fallbackImageInput((dataUrl) => {
        film.images = film.images.concat([dataUrl]);
        saveToStorage();
        renderGalleryImage();
        toast('已添加 1 张照片');
      });
    }
  });
  $('file-picker-gallery').addEventListener('change', async (e) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const film = data.films[currentFilmIndex];
    if (!film) return;
    const remaining = MAX_IMAGES - (film.images || []).length;
    if (remaining <= 0) return;
    const newImgs = await processFiles(files, remaining);
    if (newImgs.length > 0) {
      film.images = film.images.concat(newImgs);
      saveToStorage();
      // 如果当前显示的是封面，刷新显示
      renderGalleryImage();
      toast(`已添加 ${newImgs.length} 张照片`);
    }
  });
  // 编辑
  $('edit-btn').addEventListener('click', openEditModal);
  $('add-film-btn').addEventListener('click', () => {
    if (data.films.length >= 9) { toast('最多 9 个胶片'); return; }
    data.films.push({
      id: 'f' + Date.now(),
      name: '待命名胶片',
      cover: '',
      images: []
    });
    renderFilmsEditList();
  });
  $('save-edit').addEventListener('click', saveEditModal);
  $('cancel-edit').addEventListener('click', () => $('edit-modal').classList.remove('show'));

  // 自定义文字编辑后保存
  $('custom-text').addEventListener('blur', () => {
    data.customText = $('custom-text').textContent.trim() || '记忆小屋';
    saveToStorage();
  });
}

/* ===================== 背景星星生成 ===================== */
function generateStars() {
  const container = $('bg-stars');
  if (!container) return;
  const sizes = [24, 28, 32, 36, 40, 44, 50, 56];
  const starColor = '#C4DBED'; // 更淡的蓝色
  const golden = Math.PI * (3 - Math.sqrt(5));

  function makeStar(x, y) {
    const size = sizes[Math.floor(Math.random() * sizes.length)];
    const rot = Math.random() * 360;
    const star = document.createElement('div');
    star.className = 'bg-star';
    star.style.cssText = `left:${Math.max(1, Math.min(95, x))}%;top:${Math.max(1, Math.min(95, y))}%;opacity:1;transform:rotate(${rot}deg);`;
    star.innerHTML = `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="${starColor}" stroke="${starColor}" stroke-width="2" stroke-linejoin="round"><polygon points="12,2 14.5,9 22,9 16,13.5 18.5,21 12,16.5 5.5,21 8,13.5 2,9 9.5,9"/></svg>`;
    container.appendChild(star);
  }

  // 主螺旋分布（22颗）
  const mainCount = 22;
  for (let i = 0; i < mainCount; i++) {
    const r = Math.sqrt((i + 0.5) / mainCount);
    const theta = i * golden;
    const x = 50 + r * 47 * Math.cos(theta);
    const y = 50 + r * 47 * Math.sin(theta);
    makeStar(x, y);
  }

  // 左上角额外5颗（小范围Vogel螺旋，保证均匀随机）
  const cornerCount = 5;
  const corners = [
    { cx: 12, cy: 12, rx: 13, ry: 13 }, // 左上
    { cx: 12, cy: 88, rx: 13, ry: 13 }  // 左下
  ];
  for (const c of corners) {
    for (let i = 0; i < cornerCount; i++) {
      const r = Math.sqrt((i + 0.5) / cornerCount);
      const theta = i * golden;
      const x = c.cx + r * c.rx * Math.cos(theta);
      const y = c.cy + r * c.ry * Math.sin(theta);
      makeStar(x, y);
    }
  }
}

/* ===================== 初始化 ===================== */
function init() {
  generateStars();
  initSelectScene();
  bindEvents();
  // 启动页点击进入
  $('scene-splash').addEventListener('click', () => {
    showScene('scene-select');
    state = 'SELECT';
  });
  // 兼容旧数据：male→love_life，female→for_love
  if (data.gender === 'male') data.gender = 'love_life';
  if (data.gender === 'female') data.gender = 'for_love';
  // 如果有保存的数据，预选形象
  if (data.gender) {
    const card = document.querySelector(`.char-card[data-gender="${data.gender}"]`);
    if (card) {
      card.classList.add('selected');
      $('confirm-char').disabled = false;
      $('char-name-input').value = data.name || '';
    } else {
      data.gender = '';
    }
  }
  // 如果已有角色数据，跳过启动页直接进入选择
  if (data.gender && data.name) {
    showScene('scene-select');
    state = 'SELECT';
  }
}
init();